findings.codeql_raw_query:
/**
 * @name Unsafe attribute access from user input
 * @description Using getattr with user-controlled attribute names can lead to access of private attributes or methods
 * @kind path-problem
 * @problem.severity error
 * @id py/user-controlled-attribute-access
 * @tags security
 *        external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module AttributeAccessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources are function parameters that could be user-controlled
    source instanceof DataFlow::ParameterNode or
    // JSON input data
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("json").getMember(["load", "loads"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sinks are getattr calls where the attribute name is the second argument
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module AttributeAccessFlow = TaintTracking::Global<AttributeAccessConfig>;
import AttributeAccessFlow::PathGraph

from AttributeAccessFlow::PathNode source, AttributeAccessFlow::PathNode sink
where AttributeAccessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Attribute access with user-controlled name from $@.", source.getNode(), "user input"
